// значок, цвет, страница и ОДНА строка «что делает» для функций, которых сервер NurCRM как модули пока не отдаёт (их коды — MarketplaceFeatureCards.Ids;
// это предлагаемые коды модулей — как только сервер заведёт модуль с таким кодом, карточка станет обычной серверной: цена, «Включить», «+» в «Своё»).
// Тексты — только то, что программа делает сейчас (сверено по коду); цен здесь нет и быть не должно: карточка показывает серверную цену или «Цена уточняется».
public static partial class MarketplaceModuleContent
{
    // Склейка с основным словарём: ленивая, чтобы не зависеть от порядка статических инициализаторов частей класса.
    private static Dictionary<string, Spec>? _allSpecs;
    private static Dictionary<string, Spec> Specs => _allSpecs ??= Merge(CoreSpecs, FeatureSpecs());

    private static Dictionary<string, Func<string>>? _allLines;
    private static Dictionary<string, Func<string>> Lines => _allLines ??= Merge(CoreLines, FeatureLines());

    private static Dictionary<string, V> Merge<V>(Dictionary<string, V> a, Dictionary<string, V> b)
    {
        var all = new Dictionary<string, V>(a, StringComparer.OrdinalIgnoreCase);
        foreach (var (k, v) in b)
            all[k] = v;
        return all;
    }

    private static string OnlineShops() => T("Магазины с онлайн-витриной", "Онлайн-витринасы бар дүкөндөр", "Shops with an online storefront", "Çevrimiçi vitrini olan mağazalar", "Onlayn vitrinali do'konlar");
