        // ── Бот-продавец ──
        [MarketplaceFeatureCards.BotSeller] = new("robot-outline", "#0F766E", () => new(
            T("ИИ-консультант в Telegram: отвечает, берёт заказы, зовёт вас", "Telegram'да ИИ-кеңешчи: жооп берет, заказ алат, сизди чакырат", "An AI adviser in Telegram: answers, takes orders, calls you", "Telegram'da yapay zekâ danışman: yanıtlar, sipariş alır, sizi çağırır", "Telegram'da sun'iy intellekt maslahatchi: javob beradi, buyurtma oladi, sizni chaqiradi"),
            T("Покупатель пишет вашему боту в Telegram: «Есть чайник до 2 000 сом?». Бот отвечает по вашему каталогу и правилам магазина, оформляет заказ на 1 800 сом и, если покупатель просит человека, зовёт вас кнопкой «Продавец»: вы берёте диалог себе или возвращаете боту. В отчёте «Продажи бота» — диалоги, заказы, конверсия и вопросы, на которые бот не знал ответа.",
              "Сатып алуучу Telegram'дагы ботуңузга жазат: «2 000 сомго чейин чайник барбы?». Бот каталогуңуз жана дүкөндүн эрежелери боюнча жооп берет, 1 800 сомго заказ тариздейт, ал эми сатып алуучу адамды суранса, «Сатуучу» баскычы менен сизди чакырат: диалогду өзүңүзгө аласыз же ботко кайтарасыз. «Боттун сатуулары» отчётунда — диалогдор, заказдар, конверсия жана бот жоопту билбеген суроолор.",
