        [MarketplaceFeatureCards.Esf] = new("file-check-outline", "#1D4ED8", () => new(
            T("Номер ЭСФ поставщика в приходе и поиск по нему", "Келишимдеги ЭСФ номери кирешеде жана ал боюнча издөө", "The supplier's ESF number in the receipt, and search by it", "Tedarikçinin ESF numarası girişte ve onunla arama", "Yetkazib beruvchining ESF raqami kirimda va u bo'yicha qidiruv"),
            T("В «Закупки → Приём товара» впишите «№ ЭСФ поставщика» — номер сохранится вместе с приходом. Потом в «Приходах» приход находится по номеру целиком или от трёх знаков. Пример: ЭСФ 0123456789 от поставщика на 12 400 сом — по «6789» приход найден за секунду. В налоговую (ГНС) касса ничего не отправляет; выписка ЭСФ и приём входящих — отдельная задача на потом.",
              "«Сатып алуулар → Товар кабыл алуу» бөлүмүндө «Жеткирүүчүнүн ЭСФ №» жазыңыз — номер киреше менен кошо сакталат. Кийин «Кирешелерде» киреше номердин бардыгы же үч белгиден баштап табылат. Мисал: жеткирүүчүдөн 12 400 сомдук ЭСФ 0123456789 — «6789» боюнча киреше бир секундда табылат. Салык кызматына (ГНС) касса эч нерсе жөнөтпөйт; ЭСФ чыгаруу жана кирүүчүлөрдү кабыл алуу — кийинки өзүнчө милдет.",
              "In “Purchases → Receiving goods” enter “Supplier ESF no.” — the number is saved with the receipt. Later, in “Receipts” a receipt is found by the whole number or from three characters. Example: ESF 0123456789 for 12,400 som — typing “6789” finds the receipt in a second. The till sends nothing to the tax service (STS); issuing ESF and receiving incoming ones is a separate task for later.",
              "«Satın alma → Mal kabul»de «Tedarikçi ESF no.» yazın — numara girişle birlikte kaydedilir. Sonra «Girişler»de giriş numaranın tamamıyla ya da üç karakterden itibaren bulunur. Örnek: 12 400 somluk ESF 0123456789 — «6789» yazınca giriş bir saniyede bulunur. Kasa vergi idaresine (GNS) bir şey göndermez; ESF düzenleme ve gelenleri alma ayrı bir iştir, sonraya kaldı.",
              "«Xaridlar → Tovar qabul qilish»da «Yetkazib beruvchi ESF №» ni yozing — raqam kirim bilan birga saqlanadi. Keyin «Kirimlar»da kirim raqamning to'liq o'zi yoki uch belgidan boshlab topiladi. Misol: 12 400 so'mlik ESF 0123456789 — «6789» bo'yicha kirim bir soniyada topiladi. Kassa soliq xizmatiga (GNS) hech narsa yubormaydi; ESF chiqarish va kiruvchilarni qabul qilish — keyingi alohida vazifa."),
            [T("Откройте «Закупки → Приём товара» и впишите «№ ЭСФ поставщика» в шапке приёма.", "«Сатып алуулар → Товар кабыл алуу» бөлүмүн ачып, башындагы «Жеткирүүчүнүн ЭСФ №» талаасына жазыңыз.", "Open “Purchases → Receiving goods” and enter “Supplier ESF no.” in the header.", "«Satın alma → Mal kabul»ü açın ve başlıktaki «Tedarikçi ESF no.» alanına yazın.", "«Xaridlar → Tovar qabul qilish»ni oching va sarlavhadagi «Yetkazib beruvchi ESF №» maydoniga yozing."),
             T("Найти приход позже: «Закупки → Приходы» → строка поиска → номер или его конец.", "Кийин кирешени табуу: «Сатып алуулар → Кирешелер» → издөө сабы → номер же анын аягы.", "To find a receipt later: “Purchases → Receipts” → search bar → the number or its end.", "Girişi sonra bulmak için: «Satın alma → Girişler» → arama çubuğu → numara veya sonu.", "Kirimni keyin topish: «Xaridlar → Kirimlar» → qidiruv qatori → raqam yoki uning oxiri.")],
            [T("Магазины и базы, которые закупают по ЭСФ", "ЭСФ боюнча сатып алган дүкөндөр жана базалар", "Shops and depots that buy against ESF", "ESF ile alım yapan mağazalar ve depolar", "ESF bo'yicha xarid qiladigan do'konlar va bazalar"), T("Бухгалтерам: сверка прихода со счёт-фактурой", "Эсепчилерге: кирешени эсеп-фактура менен салыштыруу", "Accountants: matching receipts with the invoice", "Muhasebeciler: girişi faturayla eşleştirme", "Buxgalterlar: kirimni hisob-faktura bilan solishtirish")])),

        // ── Онлайн-ККМ ──
        [MarketplaceFeatureCards.Ekassa] = new("printer-pos", "#15803D", () => new(
            T("Чеки пробиваются через eKassa: фискальный номер и QR", "Чектер eKassa аркылуу бекитилет: фискалдык номер жана QR", "Receipts go through eKassa: fiscal number and QR", "Fişler eKassa'dan geçer: mali numara ve QR", "Cheklar eKassa orqali uriladi: fiskal raqam va QR"),
            T("Каждый чек проходит через eKassa и получает фискальный номер и QR. Режим выбирает NurCRM для вашей компании: чек пробивает касса (нужна ККМ eKassa) или сервер NurCRM — тогда отдельная ККМ не нужна. В «Настройки → Операции → Налоги и ККМ» видны режим, состояние ККМ (смена, последний чек), ставки НДС (например, 12 %) и НсП 2 %, а на чеке печатается фискальный QR. Конкретные модели ККМ программа не перечисляет: нужна ККМ, зарегистрированная в eKassa.",
              "Ар бир чек eKassa аркылуу өтүп, фискалдык номер жана QR алат. Режимди компанияңыз үчүн NurCRM тандайт: чекти касса бекитет (eKassa ККМ керек) же NurCRM сервери — анда өзүнчө ККМ керек эмес. «Жөндөөлөр → Операциялар → Салыктар жана ККМ» бөлүмүндө режим, ККМдин абалы (смена, акыркы чек), КНС ставкалары (мисалы, 12 %) жана СНС 2 % көрүнөт, ал эми чекте фискалдык QR басылат. ККМдин конкреттүү моделдерин программа санабайт: eKassa'да катталган ККМ керек.",
              "Every receipt goes through eKassa and gets a fiscal number and a QR. NurCRM sets the mode for your company: the till fiscalizes (an eKassa cash register is needed) or the NurCRM server does — then no separate cash register is needed. “Settings → Operations → Taxes and cash register” shows the mode, the register state (shift, last receipt), VAT rates (say 12 %) and sales tax 2 %, and the receipt prints a fiscal QR. The program does not list specific register models: you need a register registered in eKassa.",
              "Her fiş eKassa'dan geçer ve mali numara ile QR alır. Modu şirketiniz için NurCRM belirler: fişi kasa keser (eKassa ÖKC gerekir) ya da NurCRM sunucusu — o zaman ayrı ÖKC gerekmez. «Ayarlar → İşlemler → Vergiler ve ÖKC»de mod, ÖKC durumu (vardiya, son fiş), KDV oranları (örneğin %12) ve %2 satış vergisi görünür; fişe mali QR basılır. Program belirli ÖKC modellerini saymaz: eKassa'ya kayıtlı bir ÖKC gerekir.",
              "Har bir chek eKassa orqali o'tadi va fiskal raqam hamda QR oladi. Rejimni kompaniyangiz uchun NurCRM tanlaydi: chekni kassa uradi (eKassa KKM kerak) yoki NurCRM serveri — unda alohida KKM kerak emas. «Sozlamalar → Operatsiyalar → Soliqlar va KKM»da rejim, KKM holati (smena, oxirgi chek), QQS stavkalari (masalan, 12 %) va 2 % savdo solig'i ko'rinadi, chekda fiskal QR chop etiladi. Dastur KKMning aniq modellarini sanamaydi: eKassa'da ro'yxatdan o'tgan KKM kerak."),
            [T("Оставьте заявку в поддержку NurCRM: режим фискализации (касса или сервер) включается для компании.", "NurCRM колдоосуна өтүнмө калтырыңыз: фискалдаштыруу режими (касса же сервер) компания үчүн күйгүзүлөт.", "Leave a request with NurCRM support: the fiscalization mode (till or server) is turned on for the company.", "NurCRM desteğine talep bırakın: mali mod (kasa veya sunucu) şirket için açılır.", "NurCRM qo'llab-quvvatlashiga ariza qoldiring: fiskallashtirish rejimi (kassa yoki server) kompaniya uchun yoqiladi."),
             T("Проверьте «Настройки → Операции → Налоги и ККМ»: режим, состояние ККМ, ставки НДС и НсП.", "«Жөндөөлөр → Операциялар → Салыктар жана ККМ» бөлүмүн текшериңиз: режим, ККМ абалы, КНС жана СНС ставкалары.", "Check “Settings → Operations → Taxes and cash register”: the mode, the register state, VAT and sales-tax rates.", "«Ayarlar → İşlemler → Vergiler ve ÖKC»yi kontrol edin: mod, ÖKC durumu, KDV ve satış vergisi oranları.", "«Sozlamalar → Operatsiyalar → Soliqlar va KKM»ni tekshiring: rejim, KKM holati, QQS va savdo solig'i stavkalari.")],
            [T("Магазины, которым по закону нужен фискальный чек", "Мыйзам боюнча фискалдык чек керек болгон дүкөндөр", "Shops that need a fiscal receipt by law", "Yasal olarak mali fiş gereken mağazalar", "Qonun bo'yicha fiskal chek kerak bo'lgan do'konlar"), T("Владельцам, которые не хотят покупать отдельную ККМ (режим сервера)", "Өзүнчө ККМ сатып алгысы келбеген ээлерге (сервер режими)", "Owners who do not want to buy a separate register (server mode)", "Ayrı ÖKC almak istemeyen sahipler (sunucu modu)", "Alohida KKM sotib olishni istamagan egalar (server rejimi)")])),

        // ── Рассылки в WhatsApp ──
        [MarketplaceFeatureCards.ClientMailing] = new("account-group-outline", "#22A559", () => new(
            T("Сегменты клиентов и чаты WhatsApp по одному — отправляете вы", "Кардарлар сегменттери жана WhatsApp чаттары бирден — жөнөтүүнү өзүңүз жасайсыз", "Customer segments and WhatsApp chats one by one — you press Send", "Müşteri segmentleri ve WhatsApp sohbetleri tek tek — göndermeyi siz yaparsınız", "Mijozlar segmentlari va WhatsApp chatlari birma-bir — yuborishni o'zingiz bosasiz"),
            T("Выберите, кому писать: должникам, тем, кто не покупал 30 дней, VIP по сумме покупок, именинникам или всем с телефоном. Напишите текст с подстановками «{имя}», «{долг}» — «Открыть WhatsApp по очереди» открывает по одному чату с готовым текстом, а «Отправить» нажимаете вы. Защита от спама: «не беспокоить», не чаще раза в N дней, дневной лимит чатов, тихие часы. Пример: 18 должников — 18 чатов, в каждом имя и сумма долга.",
              "Кимге жазарыңызды тандаңыз: карыздарга, 30 күн сатып албагандарга, сатып алуу суммасы боюнча VIPге, туулган күнү барларга же телефону барлардын баарына. «{name}», «{debt}» алмаштыруулары бар текст жазыңыз — «WhatsAppты кезеги менен ачуу» даяр текст менен бир чатты ачат, ал эми «Жөнөтүүнү» өзүңүз басасыз. Спамдан коргоо: «тынчтандырбоо», N күндө бир жолудан көп эмес, күнүмдүк чат лимити, тынч саат. Мисал: 18 карыздар — 18 чат, ар биринде аты жана карыздын суммасы.",
              "Choose whom to write to: debtors, those who have not bought for 30 days, VIPs by purchase total, birthday people or everyone with a phone. Write a text with the placeholders “{name}”, “{debt}” — “Open WhatsApp one by one” opens one chat at a time with the text ready, and you press Send. Spam protection: “do not disturb”, not more than once in N days, a daily chat limit, quiet hours. Example: 18 debtors — 18 chats, each with the name and the debt amount.",
              "Kime yazacağınızı seçin: borçlulara, 30 gündür almayanlara, alışveriş tutarına göre VIP'lere, doğum günü olanlara veya telefonu olan herkese. «{name}», «{debt}» yer tutuculu bir metin yazın — «WhatsApp'ı sırayla aç» hazır metinle tek tek sohbet açar, «Gönder»e siz basarsınız. Spam koruması: «rahatsız etme», N günde bir defadan sık değil, günlük sohbet sınırı, sessiz saatler. Örnek: 18 borçlu — 18 sohbet, her birinde ad ve borç tutarı.",
              "Kimga yozishni tanlang: qarzdorlarga, 30 kundan beri xarid qilmaganlarga, xarid summasi bo'yicha VIPlarga, tug'ilgan kunlilarga yoki telefoni borlarning hammasiga. «{name}», «{debt}» o'rniga qo'yiladigan so'zlar bilan matn yozing — «WhatsApp'ni navbat bilan ochish» tayyor matn bilan bitta chatni ochadi, «Yuborish»ni o'zingiz bosasiz. Spamdan himoya: «bezovta qilmang», N kunda bir martadan ko'p emas, kunlik chat limiti, sokin soatlar. Misol: 18 qarzdor — 18 chat, har birida ism va qarz summasi."),
            [T("Откройте программу владельца → «Клиенты» → «Рассылка».", "Ээсинин программасын ачыңыз → «Кардарлар» → «Жөнөтмө».", "Open the owner's program → “Customers” → “Mailing”.", "Sahibin programını açın → «Müşteriler» → «Toplu mesaj».", "Egasining dasturini oching → «Mijozlar» → «Xabarnoma»."),
             T("Выберите сегмент, проверьте текст и нажимайте «Открыть WhatsApp по очереди»: отправляете вы.", "Сегментти тандап, текстти текшерип, «WhatsAppты кезеги менен ачууну» басыңыз: жөнөтүүнү өзүңүз жасайсыз.", "Choose a segment, check the text and press “Open WhatsApp one by one”: you do the sending.", "Segmenti seçin, metni kontrol edin ve «WhatsApp'ı sırayla aç»a basın: göndermeyi siz yaparsınız.", "Segmentni tanlang, matnni tekshiring va «WhatsApp'ni navbat bilan ochish»ni bosing: yuborishni o'zingiz qilasiz.")],
            [T("Владельцам магазинов с базой клиентов", "Кардарлар базасы бар дүкөндүн ээлерине", "Owners of shops with a customer base", "Müşteri tabanı olan mağaza sahipleri", "Mijozlar bazasi bor do'kon egalari"), T("Тем, кто возвращает долги и «давних» покупателей", "Карыздарды жана «эски» кардарларды кайтаргысы келгендер", "Those who chase debts and bring back lapsed customers", "Borç tahsil edenler ve eski müşterileri geri getirmek isteyenler", "Qarzlarni va «eski» xaridorlarni qaytarmoqchi bo'lganlar")])),

        // ── Экспорт в 1С ──
        [MarketplaceFeatureCards.OneCExport] = new("file-export-outline", "#B91C1C", () => new(
            T("Выгрузка для 1С: Excel, CSV или CommerceML за любой период", "1С үчүн чыгаруу: каалаган мезгилге Excel, CSV же CommerceML", "Export for 1C: Excel, CSV or CommerceML for any period", "1C için aktarım: her dönem için Excel, CSV veya CommerceML", "1C uchun chiqarish: istalgan davr uchun Excel, CSV yoki CommerceML"),
            T("Выберите период и что выгрузить: номенклатуру, остатки, продажи, возвраты, приходы, контрагентов — и формат: Excel, CSV или CommerceML (каталог и остатки). Файлы открываются в 1С:Розница и 1С:Бухгалтерии через «Загрузку данных из табличного документа». Суммы совпадают с отчётами до тыйына: продажи за октябрь — 412 650 сом и в отчёте, и в файле.",
              "Мезгилди жана эмнени чыгарууну тандаңыз: номенклатура, калдыктар, сатуулар, кайтаруулар, кирешелер, контрагенттер — жана форматты: Excel, CSV же CommerceML (каталог жана калдыктар). Файлдар 1С:Розница жана 1С:Бухгалтерияга «Таблицалык документтен маалыматты жүктөө» аркылуу ачылат. Суммалар отчёттор менен тыйынына чейин дал келет: октябрь айындагы сатуулар — 412 650 сом, отчётто да, файлда да.",
              "Choose the period and what to export: nomenclature, stock, sales, returns, receipts, counterparties — and the format: Excel, CSV or CommerceML (catalog and stock). The files open in 1C:Retail and 1C:Accounting through “Load data from a spreadsheet”. Amounts match the reports to the last tyiyn: October sales are 412,650 som both in the report and in the file.",
              "Dönemi ve neyi aktaracağınızı seçin: ürün listesi, stok, satışlar, iadeler, girişler, cariler — ve biçimi: Excel, CSV veya CommerceML (katalog ve stok). Dosyalar 1C:Perakende ve 1C:Muhasebe'de «Tablo belgesinden veri yükleme» ile açılır. Tutarlar raporlarla kuruşu kuruşuna eşleşir: ekim satışları hem raporda hem dosyada 412 650 som.",
              "Davrni va nimani chiqarishni tanlang: nomenklatura, qoldiqlar, sotuvlar, qaytarishlar, kirimlar, kontragentlar — va formatni: Excel, CSV yoki CommerceML (katalog va qoldiqlar). Fayllar 1C:Roznitsa va 1C:Buxgalteriyada «Jadval hujjatdan ma'lumot yuklash» orqali ochiladi. Summalar hisobotlar bilan tiyinigacha mos keladi: oktyabr sotuvlari — 412 650 so'm, hisobotda ham, faylda ham."),
            [T("Откройте «Настройки → Операции» и нажмите «Выгрузить для 1С…» (в программе владельца и у кассира с правом «Аналитика»).", "«Жөндөөлөр → Операциялар» бөлүмүн ачып, «1С үчүн чыгаруу…» баскычын басыңыз (ээсинин программасында жана «Аналитика» укугу бар кассирде).", "Open “Settings → Operations” and press “Export for 1C…” (in the owner's program and for a cashier with the “Analytics” right).", "«Ayarlar → İşlemler»i açıp «1C için aktar…»a basın (sahibin programında ve «Analiz» yetkisi olan kasiyerde).", "«Sozlamalar → Operatsiyalar»ni ochib, «1C uchun chiqarish…» tugmasini bosing (egasining dasturida va «Analitika» huquqi bor kassirda)."),
             T("Выберите период, что выгрузить и формат, сохраните файл и загрузите его в 1С.", "Мезгилди, эмнени чыгарууну жана форматты тандап, файлды сактап, 1Ске жүктөңүз.", "Choose the period, what to export and the format, save the file and load it into 1C.", "Dönemi, neyi aktaracağınızı ve biçimi seçin, dosyayı kaydedin ve 1C'ye yükleyin.", "Davrni, nimani chiqarishni va formatni tanlang, faylni saqlang va 1C ga yuklang.")],
            [T("Магазины, которые ведут учёт в 1С", "Эсепти 1Сте жүргүзгөн дүкөндөр", "Shops that keep their books in 1C", "Muhasebeyi 1C'de tutan mağazalar", "Hisobni 1C da yuritadigan do'konlar"), T("Бухгалтерам: данные периода одним файлом", "Эсепчилерге: мезгилдин маалыматы бир файлда", "Accountants: the period's data in one file", "Muhasebeciler: dönem verisi tek dosyada", "Buxgalterlar: davr ma'lumotlari bitta faylda")])),

        // ── Заполним базу ──
        [MarketplaceFeatureCards.FillBase] = new("database-arrow-right-outline", "#7E22CE", () => new(
            T("Поддержка переносит и вводит ваши товары за вас", "Колдоо кызматы товарларыңызды сиздин ордуңузга көчүрүп киргизет", "Support moves and enters your products for you", "Destek ürünlerinizi sizin yerinize taşıyıp girer", "Qo'llab-quvvatlash tovarlaringizni siz uchun ko'chirib kiritadi"),
            T("Не хотите вводить товары сами? Укажите название магазина, телефон, что у вас есть — Excel, фото накладных или выгрузка из 1С — и ссылку на файлы в облаке. Кнопка откроет WhatsApp поддержки с готовым сообщением, «Отправить» нажимаете вы. Мы переносим и вводим товары под ключ; цену и срок называет поддержка до начала работы. Например, 1 500 товаров из Excel.",
              "Товарларды өзүңүз киргизгиңиз келбейби? Дүкөндүн атын, телефонду, эмнеңиз бар экенин — Excel, накладныйлардын сүрөттөрү же 1Сттен чыгарылган файл — жана булуттагы файлдарга шилтемени жазыңыз. Баскыч даяр билдирүү менен колдоонун WhatsApp'ын ачат, «Жөнөтүүнү» өзүңүз басасыз. Товарларды ачкыч менен көчүрүп киргизебиз; баасын жана мөөнөтүн колдоо иш башталганга чейин айтат. Мисалы, Excel'ден 1 500 товар.",
              "Do not want to enter products yourself? Enter the shop name, a phone, what you have — Excel, photos of invoices or a 1C export — and a link to the files in the cloud. The button opens the support WhatsApp with a ready message, and you press Send. We move and enter the products turnkey; support names the price and the time before the work starts. For example, 1,500 products from Excel.",
              "Ürünleri kendiniz girmek istemiyor musunuz? Mağaza adını, telefonu, elinizde ne olduğunu — Excel, fatura fotoğrafları veya 1C çıktısı — ve buluttaki dosyaların bağlantısını yazın. Düğme destek WhatsApp'ını hazır mesajla açar, «Gönder»e siz basarsınız. Ürünleri anahtar teslim taşıyıp gireriz; fiyatı ve süreyi destek iş başlamadan söyler. Örneğin Excel'den 1 500 ürün.",
              "Tovarlarni o'zingiz kiritishni xohlamaysizmi? Do'kon nomi, telefon, sizda nima borligini — Excel, hisob-faktura suratlari yoki 1C dan chiqarilgan fayl — va bulutdagi fayllarga havolani yozing. Tugma qo'llab-quvvatlashning WhatsApp'ini tayyor xabar bilan ochadi, «Yuborish»ni o'zingiz bosasiz. Tovarlarni kalit topshiriq bilan ko'chirib kiritamiz; narx va muddatni ish boshlanishidan oldin qo'llab-quvvatlash aytadi. Masalan, Excel'dan 1 500 ta tovar."),
            [T("Откройте «Настройки → Операции → Перенос данных» и нажмите «Загрузим вашу базу под ключ».", "«Жөндөөлөр → Операциялар → Маалыматты көчүрүү» бөлүмүн ачып, «Базаңызды ачкыч менен жүктөйбүз» баскычын басыңыз.", "Open “Settings → Operations → Data transfer” and press “We load your catalog turnkey”.", "«Ayarlar → İşlemler → Veri aktarımı»nı açıp «Ürün tabanınızı anahtar teslim yükleriz»e basın.", "«Sozlamalar → Operatsiyalar → Ma'lumotni ko'chirish»ni ochib, «Bazangizni kalit topshiriq bilan yuklaymiz»ni bosing."),
             T("Заполните форму, вставьте ссылку на файлы и отправьте сообщение поддержке в WhatsApp.", "Форманы толтуруп, файлдарга шилтемени коюп, WhatsApp аркылуу колдоого билдирүү жөнөтүңүз.", "Fill in the form, paste the link to the files and send the message to support in WhatsApp.", "Formu doldurun, dosya bağlantısını yapıştırın ve mesajı WhatsApp'tan desteğe gönderin.", "Shaklni to'ldiring, fayllarga havolani qo'ying va xabarni WhatsApp orqali qo'llab-quvvatlashga yuboring.")],
            [T("Магазинам и базам, которые только открываются", "Жаңы ачылып жаткан дүкөндөргө жана базаларга", "Shops and depots that are just opening", "Yeni açılan mağazalar ve depolar", "Yangi ochilayotgan do'kon va bazalar"), T("Тем, у кого тысячи товаров в Excel или 1С", "Excel же 1Сте миңдеген товары барларга", "Those with thousands of products in Excel or 1C", "Excel veya 1C'de binlerce ürünü olanlar", "Excel yoki 1C da minglab tovari borlar")])),

        // ── QR магазина ──
        [MarketplaceFeatureCards.ShopQr] = new("qrcode", "#0369A1", () => new(
            T("Второй QR «Заказать онлайн» на чеке и ценнике", "Чекте жана баа белгисинде экинчи QR «Онлайн заказ»", "A second QR “Order online” on the receipt and the price tag", "Fişte ve etikette ikinci QR «Çevrimiçi sipariş»", "Chekda va narx belgisida ikkinchi QR «Onlayn buyurtma»"),
            T("На чеке печатается второй QR с подписью «Заказать онлайн»: покупатель наводит камеру и попадает на витрину вашего магазина market.nurcrm.kg/catalog/… Такой же QR можно поставить на ценник. Включается переключателем «QR витрины» в «Настройках → Печать»; по умолчанию выключен — чек не меняется. Пример: чек на 1 250 сом, внизу два QR — ссылка на электронный чек и «Заказать онлайн». Нет адреса витрины — QR не печатается.",
              "Чекте «Онлайн заказ» деген жазуусу бар экинчи QR басылат: сатып алуучу камераны багыттап, дүкөнүңүздүн витринасына market.nurcrm.kg/catalog/… түшөт. Ушундай эле QRду баа белгисине да коюуга болот. «Жөндөөлөр → Басып чыгаруу» бөлүмүндөгү «Витрина QR» которгучу менен күйгүзүлөт; демейки боюнча өчүк — чек өзгөрбөйт. Мисал: 1 250 сомдук чек, төмөндө эки QR — электрондук чекке шилтеме жана «Онлайн заказ». Витринанын дареги жок болсо — QR басылбайт.",
              "The receipt prints a second QR captioned “Order online”: the customer points the camera and lands on your shop storefront market.nurcrm.kg/catalog/… The same QR can be placed on the price tag. It is turned on with the “Storefront QR” switch in “Settings → Printing”; off by default — the receipt does not change. Example: a 1,250 som receipt with two QRs at the bottom — the e-receipt link and “Order online”. No storefront address — no QR is printed.",
              "Fişe «Çevrimiçi sipariş» yazılı ikinci bir QR basılır: müşteri kamerayı tutar ve mağazanızın vitrinine market.nurcrm.kg/catalog/… girer. Aynı QR fiyat etiketine de konabilir. «Ayarlar → Yazdırma»daki «Vitrin QR'ı» anahtarıyla açılır; varsayılan kapalı — fiş değişmez. Örnek: 1 250 somluk fişin altında iki QR — e-fiş bağlantısı ve «Çevrimiçi sipariş». Vitrin adresi yoksa QR basılmaz.",
              "Chekda «Onlayn buyurtma» yozuvli ikkinchi QR chop etiladi: xaridor kamerani yo'naltiradi va do'koningiz vitrinasiga market.nurcrm.kg/catalog/… tushadi. Xuddi shu QRni narx belgisiga ham qo'yish mumkin. «Sozlamalar → Chop etish»dagi «Vitrina QR» o'tkazgichi bilan yoqiladi; odatda o'chiq — chek o'zgarmaydi. Misol: 1 250 so'mlik chek, pastda ikkita QR — elektron chek havolasi va «Onlayn buyurtma». Vitrina manzili bo'lmasa — QR chop etilmaydi."),
            [T("«Настройки → Печать» → включите «QR витрины» (нужна подключённая онлайн-витрина).", "«Жөндөөлөр → Басып чыгаруу» → «Витрина QR» күйгүзүңүз (онлайн-витрина туташкан болушу керек).", "“Settings → Printing” → turn on “Storefront QR” (an online storefront must be connected).", "«Ayarlar → Yazdırma» → «Vitrin QR'ı»nı açın (bağlı bir çevrimiçi vitrin gerekir).", "«Sozlamalar → Chop etish» → «Vitrina QR»ni yoqing (onlayn vitrina ulangan bo'lishi kerak)."),
             T("На ценнике: «Ценники и штрихкоды» → редактор → добавьте «QR магазина».", "Баа белгисинде: «Баа белгилери жана штрихкоддор» → редактор → «Дүкөндүн QRун» кошуңуз.", "On the price tag: “Price tags and barcodes” → editor → add “Shop QR”.", "Etikette: «Etiketler ve barkodlar» → düzenleyici → «Mağaza QR'ı» ekleyin.", "Narx belgisida: «Narx belgilari va shtrixkodlar» → muharrir → «Do'kon QR»ni qo'shing.")],
            [OnlineShops(), T("Тем, кто хочет вести покупателей с бумаги в онлайн", "Кардарларды кагаздан онлайнга алып чыккысы келгендер", "Those who want to lead customers from paper to online", "Müşteriyi kağıttan çevrimiçine yönlendirmek isteyenler", "Xaridorlarni qog'ozdan onlaynga olib chiqmoqchi bo'lganlar")])),

        // ── QR на сумму чека ──
        [MarketplaceFeatureCards.PaymentQr] = new("qrcode-scan", "#BE185D", () => new(
